// Generated by the Salvo compiler: structural comparison.
package salvo

// [col-hashed-ordered] [kt-ordered] The comparison a struct's generated
// `compareTo` uses for each field — the one `: default Ordered<self>` asks for
// [cmp-default] — and what the canonical `cmp(Str, Str)` lowers to.
//
// A plain `field.compareTo(other.field)` is not enough on this backend: an
// `Int` or a `Str` is `Comparable`, but a **List** is not, and neither is a
// `Pair` or a `Triple` — while Salvo says a list or a tuple is orderable
// exactly when its elements are (user decision 2026-09-12), and Rust agrees
// for free (`Vec<T>: Ord` when `T: Ord`, and tuples likewise). This helper is
// what closes that gap, so the two backends order the same values the same
// way.
//
// Lists and tuples compare **lexicographically**, element by element; a
// shorter list that is a prefix of a longer one compares less.

// [kt-tuple-class] What a *generated* tuple — the arities past `Pair` and
// `Triple`, which Kotlin has no type for — exposes so this helper can order it
// without knowing its arity. A type test is the only way in (there is no
// supertype Kotlin already knows), so the tuple classes implement this and
// hand over their elements in order.
interface SalvoTuple {
    val __parts: List<Any?>
}

@Suppress("UNCHECKED_CAST")
fun __salvoCompare(a: Any?, b: Any?): Int {
    // Strings compare by **code point**, not by UTF-16 code unit.
    //
    // `String.compareTo` on the JVM compares `char`s, i.e. UTF-16 code units,
    // which puts a supplementary-plane character (encoded as a surrogate
    // pair, 0xD800–0xDFFF) *below* one in the private-use area 0xE000–0xFFFF
    // — while Rust's `String: Ord` is byte-wise UTF-8, which is code-point
    // order. Salvo already decided that a string is a sequence of characters
    // rather than of encoding units (string indexing made the same call), so
    // this is the reading that keeps a `SortedSet<Str>` in the same order on
    // both backends [col-hashed-ordered].
    if (a is String && b is String) {
        val ap = a.codePoints().toArray()
        val bp = b.codePoints().toArray()
        val n = if (ap.size < bp.size) ap.size else bp.size
        for (i in 0 until n) {
            if (ap[i] != bp[i]) return ap[i].compareTo(bp[i])
        }
        return ap.size.compareTo(bp.size)
    }
    if (a is List<*> && b is List<*>) {
        val n = if (a.size < b.size) a.size else b.size
        for (i in 0 until n) {
            val c = __salvoCompare(a[i], b[i])
            if (c != 0) return c
        }
        return a.size.compareTo(b.size)
    }
    if (a is Pair<*, *> && b is Pair<*, *>) {
        val c = __salvoCompare(a.first, b.first)
        return if (c != 0) c else __salvoCompare(a.second, b.second)
    }
    if (a is Triple<*, *, *> && b is Triple<*, *, *>) {
        val c1 = __salvoCompare(a.first, b.first)
        if (c1 != 0) return c1
        val c2 = __salvoCompare(a.second, b.second)
        return if (c2 != 0) c2 else __salvoCompare(a.third, b.third)
    }
    // [kt-tuple-class] A generated tuple orders by its elements, which is the
    // list rule applied to `__parts` — same arity on both sides, so the
    // length tie-break never fires.
    if (a is SalvoTuple && b is SalvoTuple) {
        return __salvoCompare(a.__parts, b.__parts)
    }
    // Everything else Salvo admits as orderable is `Comparable` on the JVM:
    // `Int`, `Long`, `Str`, `Char`, `Bool`, and a struct with a generated
    // `compareTo`, which this reaches.
    return (a as Comparable<Any?>).compareTo(b)
}

/**
 * [platform-check] [kt-platform-check] Salvo's canonical ordering as one
 * comparator object, so a sorted collection can be asked whether it is sorted
 * the program's way (`comparator() === SalvoCanonicalOrder`): a `TreeSet` of
 * `String`s under natural ordering sorts by UTF-16 code unit, Salvo by code
 * point. What every sorted collection under the canonical ordering is built
 * with, and what host code builds one with ([salvoSortedSetOf]).
 */
object SalvoCanonicalOrder : java.util.Comparator<Any?> {
    override fun compare(a: Any?, b: Any?): Int = __salvoCompare(a, b)
}

/** [platform-check] A `SortedSet` under Salvo's canonical ordering, for host code. */
fun <T> salvoSortedSetOf(vararg elems: T): java.util.TreeSet<T> =
    java.util.TreeSet<T>(SalvoCanonicalOrder).also { it.addAll(elems) }

/** [platform-check] A `SortedMap` under Salvo's canonical ordering, for host code. */
fun <K, V> salvoSortedMapOf(vararg entries: Pair<K, V>): java.util.TreeMap<K, V> =
    java.util.TreeMap<K, V>(SalvoCanonicalOrder).also { m -> entries.forEach { m[it.first] = it.second } }

// [platform-check] What an adapter applies to a set or map the host returns
// (ABI.md D10 C1, C2): the same value when it already keeps Salvo's order, a
// copy that does otherwise.
fun <T> __salvoInsertionOrdered(s: Set<T>): Set<T> =
    if (s.size <= 1 || s is java.util.LinkedHashSet<*>) s else java.util.LinkedHashSet(s)
@JvmName("__salvoInsertionOrderedMutableSet")
fun <T> __salvoInsertionOrdered(s: MutableSet<T>): MutableSet<T> =
    if (s is java.util.LinkedHashSet<*>) s else java.util.LinkedHashSet(s)
fun <K, V> __salvoInsertionOrdered(m: Map<K, V>): Map<K, V> =
    if (m.size <= 1 || m is java.util.LinkedHashMap<*, *>) m else java.util.LinkedHashMap(m)
@JvmName("__salvoInsertionOrderedMutableMap")
fun <K, V> __salvoInsertionOrdered(m: MutableMap<K, V>): MutableMap<K, V> =
    if (m is java.util.LinkedHashMap<*, *>) m else java.util.LinkedHashMap(m)
fun <T> __salvoCanonicalSorted(s: java.util.SortedSet<T>): java.util.SortedSet<T> =
    if (s.comparator() === SalvoCanonicalOrder) s else java.util.TreeSet<T>(SalvoCanonicalOrder).also { it.addAll(s) }
fun <K, V> __salvoCanonicalSorted(m: java.util.SortedMap<K, V>): java.util.SortedMap<K, V> =
    if (m.comparator() === SalvoCanonicalOrder) m else java.util.TreeMap<K, V>(SalvoCanonicalOrder).also { it.putAll(m) }
